import Foundation
private let offset: UInt64 = 1_469_598_103_934_665_603
private let prime: UInt64 = 1_099_511_628_211
private func hash(_ seed: UInt64, _ value: UInt64) -> UInt64 { var result = seed; for index in 0..<8 { result ^= (value >> UInt64(index * 8)) & 255; result &*= prime }; return result }
@main struct SM64MrBlizzardSnowballSmoke { static func main() { let hold = SM64MrBlizzardSnowballBehavior.update(.init(action: 0, timer: 0, position: .zero, velocityY: 0, gravity: -4, moveYaw: 0, forwardVelocity: 5, parentHolding: true, parentThrowing: false, parentYaw: 0, distanceToMario: 100, onGround: false, enteredWater: false)); let launch = SM64MrBlizzardSnowballBehavior.update(.init(action: 1, timer: 1, position: .zero, velocityY: 0, gravity: -4, moveYaw: 0, forwardVelocity: 5, parentHolding: false, parentThrowing: true, parentYaw: 1000, distanceToMario: 100, onGround: false, enteredWater: false)); let delete = SM64MrBlizzardSnowballBehavior.update(.init(action: 2, timer: 3, position: .zero, velocityY: 0, gravity: -4, moveYaw: 0, forwardVelocity: 40, parentHolding: false, parentThrowing: false, parentYaw: 0, distanceToMario: 0, onGround: true, enteredWater: false)); precondition(hold.action == 1 && launch.action == 2 && launch.forwardVelocity == 40 && launch.velocityY == -12.5); precondition(delete.shouldDelete && delete.spawnWhiteParticles); var fingerprint = offset; for output in [hold, launch, delete] { fingerprint = hash(fingerprint, UInt64(bitPattern: Int64(output.action))); fingerprint = hash(fingerprint, UInt64(bitPattern: Int64(output.timer))); fingerprint = hash(fingerprint, UInt64(bitPattern: Int64(output.moveYaw))); fingerprint = hash(fingerprint, UInt64(output.forwardVelocity.bitPattern)); fingerprint = hash(fingerprint, output.shouldDelete ? 1 : 0) }; print(String(format: "mrBlizzardSnowballFingerprint=0x%016llx", fingerprint)); print("SM64 Modern Mr Blizzard snowball smoke passed") } }
